passos.comando:
SELECT file#, block#, blocks, corruption_change#, corruption_type
FROM v$database_block_corruption ORDER BY file#, block#;

-- corrupcao ja detectada dentro de backups:
SELECT * FROM v$backup_corruption ORDER BY piece#;
SELECT * FROM v$copy_corruption;

RMAN> VALIDATE CHECK LOGICAL DATABASE;

-- ou, para restringir a um datafile e ir mais rapido:
RMAN> VALIDATE CHECK LOGICAL DATAFILE <file#>;

SELECT db_unique_name, database_role, protection_mode, force_logging
FROM v$database;

SELECT name, value FROM v$dataguard_stats
WHERE name IN ('transport lag','apply lag');

RMAN> RECOVER DATAFILE <file#> BLOCK <block#>;

-- ou, para tudo que o banco ja marcou como corrompido:
RMAN> RECOVER CORRUPTION LIST;

-- 1) salvar o que ainda e legivel (pulando o bloco ruim, com DBMS_REPAIR
--    ja aplicado pelo procedimento aprovado):
CREATE TABLE <owner>.<tabela>_salva AS SELECT * FROM <owner>.<tabela>;

-- 2) medir a perda comparando com a contagem esperada:
SELECT COUNT(*) FROM <owner>.<tabela>_salva;

SELECT name, value, isdefault FROM v$parameter
WHERE name IN ('db_block_checking','db_block_checksum',
               'db_lost_write_protect','db_ultra_safe');

SELECT force_logging FROM v$database;

SELECT tablespace_name, force_logging, contents
FROM dba_tablespaces WHERE force_logging = 'NO';
